const email = $json;

const fromData = email.from;
let senderEmail = '';
let senderName = '';

if (typeof fromData === 'string') {
  const emailMatch = fromData.match(
    /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i
  );

  senderEmail = emailMatch?.[0] || fromData;
} else if (fromData && typeof fromData === 'object') {
  const firstSender = Array.isArray(fromData.value)
    ? fromData.value[0]
    : null;

  senderEmail =
    firstSender?.address ||
    fromData.address ||
    '';

  senderName =
    firstSender?.name ||
    fromData.name ||
    '';
}

const sender = senderName
  ? `${senderName} <${senderEmail}>`
  : senderEmail;

const body = String(
  email.text ||
  email.textAsHtml ||
  email.html ||
  email.snippet ||
  ''
)
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 12000);

return {
  message_id: email.id,
  thread_id: email.threadId,
  sender,
  sender_email: senderEmail,
  recipient: String(email.to?.text || email.to || ''),
  subject: String(email.subject || '(No subject)'),
  received_at: String(email.date || ''),
  body,
  gmail_url: `https://mail.google.com/mail/u/0/#inbox/${
    email.threadId || email.id
  }`,
};

