const source = $('Prepare Email').item.json;
const allowed = {
  department: ['Finance', 'Sales', 'Support', 'HR', 'Operations', 'General'],
  type: ['Invoice', 'Payment', 'Complaint', 'Inquiry', 'Meeting', 'Job Application', 'Other'],
  priority: ['Urgent', 'Normal']
};

let parsed = {};
try {
  const raw = $json.choices?.[0]?.message?.content ?? '';
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  parsed = {};
}

const department = allowed.department.includes(parsed.department) ? parsed.department : 'General';
const type = allowed.type.includes(parsed.type) ? parsed.type : 'Other';
const priority = allowed.priority.includes(parsed.priority) ? parsed.priority : 'Normal';
const confidenceNumber = Number(parsed.confidence);
const confidence = Number.isFinite(confidenceNumber) ? Math.max(0, Math.min(1, confidenceNumber)) : 0;
const needsReview = confidence < 0.75;
const draftReply = String(parsed.draft_reply || '').trim().slice(0, 4000);
const draftRequired = Boolean(parsed.draft_required && draftReply);

return {
  ...source,
  department,
  email_type: type,
  priority,
  confidence,
  summary: String(parsed.summary || 'AI classification needs manual review.').trim().slice(0, 500),
  urgency_reason: String(parsed.urgency_reason || '').trim().slice(0, 500),
  draft_required: draftRequired,
  draft_reply: draftReply,
  needs_review: needsReview,
  is_urgent: priority === 'Urgent',
  desired_label_names: [
    `AI/Department/${department}`,
    `AI/Type/${type}`,
    `AI/Priority/${priority}`,
    ...(needsReview ? ['AI/Needs Review'] : [])
  ]
};

const analyses = $('Validate AI Output').all().map(item => item.json);
const labels = $input.all().map(item => item.json);

const byName = Object.fromEntries(
  labels.map(label => [label.name, label.id])
);

return analyses.map((analysis, index) => {
  const labelIds = analysis.desired_label_names
    .map(name => byName[name])
    .filter(Boolean);

  const missingLabels = analysis.desired_label_names
    .filter(name => !byName[name]);

  if (!labelIds.length) {
    throw new Error(
      'No AI labels were found. Make sure the label setup was completed.'
    );
  }

  return {
    json: {
      ...analysis,
      label_ids: labelIds,
      missing_labels: missingLabels,
    },
    pairedItem: {
      item: index,
    },
  };
});

